def is_emirp(n):
    def is_prime(x):
        if x < 2:
            return False
        if x < 4:
            return True
        if x % 2 == 0:
            return False
        i = 3
        while i * i <= x:
            if x % i == 0:
                return False
            i += 2
        return True
    reversed_n = int(str(n)[::-1])
    return is_prime(n) and is_prime(reversed_n) and reversed_n != n

def find_longest_common_suffix_length(a, b):
