def render_row_truncate_pad(cells, widths):
    columns = []
    for cell, width in zip(cells, widths):
        if len(cell) > width:
            columns.append(cell[:width])
        else:
            columns.append(cell + ' ' * (width - len(cell)))
    return ' '.join(columns)

