def is_valid_grid_reference(s):
    if len(s) < 2 or not s[0].isupper() or not s[0].isalpha():
        return False
    rest = s[1:]
    if not rest.isdigit():
        return False
    if rest[0] == '0' and len(rest) > 1:
        return False
    value = int(rest)
    return 1 <= value <= 99

