def tokenize_mixed_alnum(s):
    tokens = []
    current = ""
    for ch in s:
        if ch.isalnum():
            if current and (current[-1].isalpha() != ch.isalpha()):
                tokens.append(current)
                current = ""
            current += ch
        else:
            if current:
                tokens.append(current)
                current = ""
    if current:
        tokens.append(current)
    return tokens

def pascal_case_join(words):
    parts = []
    for w in words:
        parts.append(w[:1].upper() + w[1:])
    return ''.join(parts)

